    oled.print("max "); oled.print(tMax, 1); oled.print("  min "); oled.print(tMin, 1);
    oled.display();
  }
  delay(1000);
}

#include <Arduino.h>

const int MQ = PA0, GREEN = PA1, RED = PA2, BUZZ = PA3;
int baseline = 0;
unsigned long overSince = 0;

void setup() {
  Serial.begin(115200);
  pinMode(GREEN, OUTPUT); pinMode(RED, OUTPUT); pinMode(BUZZ, OUTPUT);
  Serial.println("预热 60 秒（正式使用建议 3 分钟以上）...");
  delay(60000);
  long sum = 0;
  for (int i = 0; i < 50; i++) { sum += analogRead(MQ); delay(20); }
  baseline = sum / 50;                  // 干净空气基线
  Serial.print("基线: "); Serial.println(baseline);
}

void loop() {
  int v = analogRead(MQ);
  Serial.println(v);                    // Serial Plotter 直接画曲线
  bool bad = v > baseline * 1.5;
  digitalWrite(GREEN, !bad); digitalWrite(RED, bad);

  if (bad) {
    if (overSince == 0) overSince = millis();
    if (millis() - overSince > 3000) digitalWrite(BUZZ, HIGH);   // 持续 3 秒才响
  } else {
    overSince = 0; digitalWrite(BUZZ, LOW);
  }
  delay(200);
}

#include <Arduino.h>

const int PROBE = PA0;
const int GEN = PA1;                 // 自带信号源：PWM
const unsigned long INTERVAL_US = 2000;   // 采样间隔 2ms = 500Hz
unsigned long lastUs = 0;

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);          // 0-4095
  pinMode(GEN, OUTPUT);
  analogWrite(GEN, 64);              // 25% 占空比方波
}

void loop() {
  unsigned long now = micros();
  if (now - lastUs < INTERVAL_US) return;
  lastUs = now;
  int raw = analogRead(PROBE);
  float volt = raw * 3.3f / 4095.0f;
  // Serial Plotter 格式：数值 空格 数值 换行。第二列固定 3.3 当参考线
  Serial.print(volt, 3); Serial.print(' '); Serial.println(3.3);
}

#include <Arduino.h>
#include <OneWire.h>
#include <DallasTemperature.h>

OneWire ow(PB12);
DallasTemperature temp(&ow);
const int FAN = PA8, POT = PA0;
const float T_MIN = 25, T_MAX = 35;
const int DUTY_MIN = 80;                 // 低于这个电机不转

void setup() {
  Serial.begin(115200);
  temp.begin();
  pinMode(FAN, OUTPUT);
  analogWriteFrequency(25000);           // 25kHz，人耳听不到
  analogWrite(FAN, 0);
}

void loop() {
  temp.requestTemperatures();
  float t = temp.getTempCByIndex(0);
  int pot = analogRead(POT);             // 0-1023
  int duty;
  if (pot < 30) {                        // 拧到底 = 自动模式
    duty = map(constrain((int)(t * 10), T_MIN * 10, T_MAX * 10), T_MIN * 10, T_MAX * 10, 0, 255);
  } else {
    duty = map(pot, 0, 1023, 0, 255);   // 手动
  }
  if (duty > 0 && duty < DUTY_MIN) duty = DUTY_MIN;
  analogWrite(FAN, duty);
  Serial.print(t, 1); Serial.print(" C  duty "); Serial.println(duty);
  delay(500);
}

#include <Arduino.h>

HardwareSerial BT(PA3, PA2);   // RX, TX -> USART2 接 HC-05
const int IN1 = PB12, IN2 = PB13, IN3 = PB14, IN4 = PB15;
const int ENA = PA8, ENB = PB8;
int speedPwm = 180;
unsigned long lastCmd = 0;

void drive(int l, int r) {   // -1 后退 0 停 1 前进
  digitalWrite(IN1, l > 0); digitalWrite(IN2, l < 0);
  digitalWrite(IN3, r > 0); digitalWrite(IN4, r < 0);
  analogWrite(ENA, l ? speedPwm : 0);
  analogWrite(ENB, r ? speedPwm : 0);
}

void setup() {
  Serial.begin(115200);
  BT.begin(9600);              // HC-05 出厂默认 9600
  for (int p : {IN1, IN2, IN3, IN4, ENA, ENB}) pinMode(p, OUTPUT);
  drive(0, 0);
}

void loop() {
  if (BT.available()) {
    char c = BT.read();
    lastCmd = millis();
    Serial.print("收到: "); Serial.println(c);
    switch (c) {
      case 'F': drive(1, 1); break;
      case 'B': drive(-1, -1); break;
      case 'L': drive(-1, 1); break;
      case 'R': drive(1, -1); break;
      case 'S': drive(0, 0); break;
      default:
        if (c >= '0' && c <= '9') speedPwm = map(c - '0', 0, 9, 90, 255);
    }
  }
  if (millis() - lastCmd > 500) drive(0, 0);   // 失联保护
}

#include <Arduino.h>

const int IN1 = PB12, IN2 = PB13, IN3 = PB14, IN4 = PB15, ENA = PA8, ENB = PB8;
const int SENS_L = PB10, SENS_R = PB11;
const int FAST = 170, SLOW = 90;
int lastDir = 0;           // -1 左 1 右
unsigned long lostSince = 0;

void motors(int lSpeed, int rSpeed) {      // 正前进 负后退
  digitalWrite(IN1, lSpeed > 0); digitalWrite(IN2, lSpeed < 0);
  digitalWrite(IN3, rSpeed > 0); digitalWrite(IN4, rSpeed < 0);
  analogWrite(ENA, abs(lSpeed)); analogWrite(ENB, abs(rSpeed));
}

void setup() {
  for (int p : {IN1, IN2, IN3, IN4, ENA, ENB}) pinMode(p, OUTPUT);
  pinMode(SENS_L, INPUT); pinMode(SENS_R, INPUT);
}

void loop() {
  bool L = digitalRead(SENS_L);   // 1 = 看到黑线
  bool R = digitalRead(SENS_R);
  if (L && R) { motors(0, 0); return; }          // 终点：两边都黑
  if (!L && !R) {                                 // 线在两探头之间：直走
    if (lostSince == 0) lostSince = millis();
    if (millis() - lostSince > 1000) {            // 丢线太久：按上次方向找
      if (lastDir < 0) motors(SLOW, FAST); else motors(FAST, SLOW);
    } else motors(FAST, FAST);
  } else {
    lostSince = 0;
    if (L) { motors(SLOW, FAST); lastDir = -1; }  // 左边压线：左转
    else   { motors(FAST, SLOW); lastDir = 1; }   // 右边压线：右转
  }
}

#include <Arduino.h>
#include <IRremote.hpp>       // IRremote 4.x

const int IR_PIN = PB12, RELAY = PB13, LED1 = PA1, LED2 = PA2;
// 先跑一遍打印出你遥控器的键值，替换下面几个
const uint16_t KEY_1 = 0x0C, KEY_2 = 0x18, KEY_0 = 0x16;
bool s1 = false, s2 = false;

void setup() {
  Serial.begin(115200);
  IrReceiver.begin(IR_PIN, ENABLE_LED_FEEDBACK);
  pinMode(RELAY, OUTPUT); pinMode(LED1, OUTPUT); pinMode(LED2, OUTPUT);
  digitalWrite(RELAY, HIGH);   // 低电平触发模块：HIGH = 断开
}

void loop() {
  if (!IrReceiver.decode()) return;
  auto &d = IrReceiver.decodedIRData;
  if (!(d.flags & IRDATA_FLAGS_IS_REPEAT)) {      // 忽略按住不放的重复码
    Serial.print("协议 "); Serial.print(getProtocolString(d.protocol));
    Serial.print(" 命令 0x"); Serial.println(d.command, HEX);
    if (d.command == KEY_1) { s1 = !s1; digitalWrite(LED1, s1); digitalWrite(RELAY, s1 ? LOW : HIGH); }
    if (d.command == KEY_2) { s2 = !s2; digitalWrite(LED2, s2); }
    if (d.command == KEY_0) { s1 = s2 = false; digitalWrite(LED1, 0); digitalWrite(LED2, 0); digitalWrite(RELAY, HIGH); }
  }
  IrReceiver.resume();          // 准备收下一个
}

#include <Arduino.h>
#include <Wire.h>
#include <Adafruit_MPU6050.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

Adafruit_MPU6050 mpu;
Adafruit_SSD1306 oled(128, 64, &Wire, -1);
const int BTN = PB12;
const float THRESHOLD = 12.5;        // m/s^2，静止约 9.8，走路峰值 12-15
unsigned long lastStep = 0, lastDraw = 0;
int steps = 0;
bool above = false;

void setup() {
  Serial.begin(115200);
  Wire.begin();
  if (!mpu.begin()) { Serial.println("找不到 MPU6050"); while (1); }
  mpu.setAccelerometerRange(MPU6050_RANGE_4_G);
  mpu.setFilterBandwidth(MPU6050_BAND_21_HZ);   // 滤掉高频抖动
  oled.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  oled.setTextColor(WHITE);
  pinMode(BTN, INPUT_PULLUP);
}

void loop() {
  sensors_event_t a, g, t;
  mpu.getEvent(&a, &g, &t);
  float mag = sqrt(a.acceleration.x * a.acceleration.x + a.acceleration.y * a.acceleration.y + a.acceleration.z * a.acceleration.z);
  Serial.println(mag);               // Plotter 看波形调阈值

  // 上穿阈值算一步，两步至少间隔 300ms
  if (mag > THRESHOLD && !above && millis() - lastStep > 300) { steps++; lastStep = millis(); }
  above = mag > THRESHOLD;

  if (digitalRead(BTN) == LOW) steps = 0;
  if (millis() - lastDraw > 200) {
    lastDraw = millis();
    oled.clearDisplay(); oled.setTextSize(4); oled.setCursor(0, 16); oled.print(steps); oled.display();
  }
  delay(20);                         // 约 50Hz 采样
}

