#include <Arduino.h>
#include <Servo.h>

Servo curtain;
const int SERVO = PA0, LDR = PA1, BTN = PB12;
const int OPEN_DEG = 170, CLOSE_DEG = 10;
const int BRIGHT = 600, DARK = 300;          // 滞回两个阈值
int current = CLOSE_DEG;
bool isOpen = false;
unsigned long darkSince = 0, brightSince = 0, manualUntil = 0;
int lastBtn = HIGH;

void moveTo(int target) {                      // 慢慢转，像人拉
  while (current != target) {
    current += (target > current) ? 1 : -1;
    curtain.write(current);
    delay(15);
  }
}

void setup() {
  curtain.attach(SERVO);
  curtain.write(current);
  pinMode(BTN, INPUT_PULLUP);
}

void loop() {
  int b = digitalRead(BTN);
  if (b == LOW && lastBtn == HIGH) {
    isOpen = !isOpen; moveTo(isOpen ? OPEN_DEG : CLOSE_DEG);
    manualUntil = millis() + 30UL * 60 * 1000;   // 手动后 30 分钟不自动
    delay(50);
  }
  lastBtn = b;
  if (millis() < manualUntil) return;

  int light = analogRead(LDR);
  // 亮/暗都要持续 60 秒才算真的变天
  if (light > BRIGHT) { if (!brightSince) brightSince = millis(); darkSince = 0; }
  else if (light < DARK) { if (!darkSince) darkSince = millis(); brightSince = 0; }
  else { brightSince = darkSince = 0; }

  if (!isOpen && brightSince && millis() - brightSince > 60000) { isOpen = true; moveTo(OPEN_DEG); }
  if (isOpen && darkSince && millis() - darkSince > 60000) { isOpen = false; moveTo(CLOSE_DEG); }
  delay(200);
}

